"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are expanded in place with the contents of the
    referenced file, resolved relative to the including file's directory.
    """
    with open(path, "r", encoding="utf-8") as fh:
        lines = fh.read().splitlines()
    real = os.path.realpath(path)
    return parse_lines(_expand(lines, real, [real]))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())


def _expand(lines, path, stack):
    base = os.path.dirname(path)
    result = []
    for raw in lines:
        parts = raw.strip().split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            result.append(raw)
            continue
        if len(parts) < 2:
            raise ConfigError("{}: @include requires a path".format(path))
        target = os.path.realpath(os.path.join(base, parts[1].strip()))
        if target in stack:
            chain = " -> ".join(stack + [target])
            raise ConfigError("include cycle detected: {}".format(chain))
        if not os.path.isfile(target):
            raise ConfigError(
                "{}: included file not found: {}".format(path, parts[1].strip())
            )
        try:
            with open(target, "r", encoding="utf-8") as fh:
                included = fh.read().splitlines()
        except OSError as exc:
            raise ConfigError(
                "{}: cannot read included file {}: {}".format(path, target, exc)
            )
        result.extend(_expand(included, target, stack + [target]))
    return result
